window.onload=init;let preferenceButton=document.getElementById("savePref").addEventListener("click",savePref),themeSelect=document.getElementById("theme"),optDark=document.getElementById("optDark"),optLight=document.getElementById("optLight"),tableRadio=document.getElementById("table"),gridRadio=document.getElementById("grid");const toastLive=document.getElementById("notificationToast");function init(){let e=localStorage.getItem("theme")||"light",t=localStorage.getItem("display")||"table";"dark"==e?(optDark.setAttribute("selected","selected"),optLight.removeAttribute("selected"),updateTheme(e)):"light"==e&&(optLight.setAttribute("selected","selected"),optDark.removeAttribute("selected"),updateTheme(e)),t&&(document.getElementById(t).checked=!0),fetch("../json/promo.json").then(e=>e.json()).then(e=>updateInformations(e))}function savePref(e){e.preventDefault();let t=tableRadio.checked?"table":gridRadio.checked?"grid":"";localStorage.setItem("theme",themeSelect.value),localStorage.setItem("display",t),updateTheme(themeSelect.value),bootstrap.Toast.getOrCreateInstance(toastLive).show()}function updateTheme(e){document.documentElement.setAttribute("data-bs-theme",e)}function updateInformations(e){document.querySelector("h1[nomPromo]").innerText=e.nomPromo}